export async function loadLazySvelteComponent<TComponent>(
  loadModule: () => Promise<{ default: TComponent }>,
): Promise<LazySvelteComponentLoadObservation<TComponent>> {
  if (typeof loadModule !== 'function') {
    throw new Error('kiwiclaw-lazy-svelte-component-loader-mismatch');
  }
  const boundary = {
    importAttempted: true,
    routeActivationRequired: true,
    privateFailureDetailExposed: false,
    externalNetworkAuthorityGranted: false,
    runtimeModuleAuthorityGranted: false,
    domainEffectsAuthorized: false,
  } as const;
  try {
    const loaded = await loadModule();
    if (loaded === null
      || typeof loaded !== 'object'
      || typeof loaded.default !== 'function') {
      return {
        state: 'rejected',
        component: null,
        moduleDefaultVerified: false,
        ...boundary,
      };
    }
    return {
      state: 'loaded',
      component: loaded.default,
      moduleDefaultVerified: true,
      ...boundary,
    };
  } catch {
    return {
      state: 'rejected',
      component: null,
      moduleDefaultVerified: false,
      ...boundary,
    };
  }
}

